// Decision S46-D1: covergroup instances without option.name get distinct
// default names, and set_inst_name replaces the name. The case prints only
// whether the names differ, not the tool's naming scheme.
//
// IEEE 1800-2009 Table 19-1 (SystemVerilog-1800-2009.txt L33265-33267):
// "name=string unique name Specifies a name for the covergroup instance. If
// unspecified, a unique name for each instance is automatically generated by
// the tool." 19.8 Table 19-5 (L33559-33560): "void set_inst_name(string) ...
// Sets the instance name to the given string".
module tb;
  bit [1:0] a;
  covergroup g;
    coverpoint a;
  endgroup
  g g1 = new, g2 = new;
  initial begin
    $display("distinct %0d", g1.option.name != g2.option.name);
    $display("nonempty %0d", g1.option.name.len() > 0);
    g2.set_inst_name("second");
    $display("%s", g2.option.name);
    $finish;
  end
endmodule
